/**
 * A curated pairing library (22.2): two dozen display and body pairs, every
 * face open-licensed (OFL-1.1) and shipped with the app, grouped by voice.
 *
 * ── Why this is a batch item and not a list ─────────────────────────────────
 *
 * Batch 4 found that measuring with one typeface and rendering with another
 * overflowed three slides in four (D1), and that a CSS stack was being handed
 * where a FONTS id was expected (F1). So every face named here is a
 * `MeasuredId`: generated by `npm run build:fonts` from the files the browser
 * renders, with its advances and kerning. A pair naming a face with no metrics
 * does not compile, and `pairs.test.ts` builds a deck in every pair, at every
 * format, and asserts zero overflow.
 *
 * Choosing a pair sets the theme's two faces and nothing else. It is applied
 * once, like every style, and the layers it touches are ordinary layers.
 */
import type { MeasuredId } from "../render/fonts/ids.js";
import type { Theme } from "./presets.js";

export type Voice = "editorial" | "technical" | "friendly" | "luxury" | "brutal" | "handwritten";

export const VOICES: { id: Voice; label: string }[] = [
  { id: "editorial", label: "Editorial" },
  { id: "technical", label: "Technical" },
  { id: "friendly", label: "Friendly" },
  { id: "luxury", label: "Luxury" },
  { id: "brutal", label: "Brutal" },
  { id: "handwritten", label: "Handwritten" },
];

export type Pair = {
  id: string;
  name: string;
  voice: Voice;
  display: MeasuredId;
  body: MeasuredId;
};

export const PAIRS: Pair[] = [
  { id: "broadsheet", name: "Broadsheet", voice: "editorial", display: "playfair", body: "sourceserif" },
  { id: "essay", name: "Essay", voice: "editorial", display: "fraunces", body: "inter" },
  { id: "column", name: "Column", voice: "editorial", display: "dmserif", body: "dmsans" },
  { id: "review", name: "Review", voice: "editorial", display: "baskerville", body: "lato" },

  { id: "spec", name: "Spec", voice: "technical", display: "spacegrotesk", body: "inter" },
  { id: "changelog", name: "Changelog", voice: "technical", display: "plexsans", body: "plexmono" },
  { id: "terminal", name: "Terminal", voice: "technical", display: "jetbrains", body: "inter" },
  { id: "lab", name: "Lab", voice: "technical", display: "spacemono", body: "worksans" },

  { id: "hello", name: "Hello", voice: "friendly", display: "poppins", body: "opensans" },
  { id: "round", name: "Round", voice: "friendly", display: "nunito", body: "nunito" },
  { id: "chat", name: "Chat", voice: "friendly", display: "rubik", body: "karla" },
  { id: "soft", name: "Soft", voice: "friendly", display: "quicksand", body: "lato" },

  { id: "maison", name: "Maison", voice: "luxury", display: "cormorant", body: "montserrat" },
  { id: "atelier", name: "Atelier", voice: "luxury", display: "bodoni", body: "jost" },
  { id: "gala", name: "Gala", voice: "luxury", display: "cinzel", body: "raleway" },
  { id: "salon", name: "Salon", voice: "luxury", display: "marcellus", body: "lato" },

  { id: "poster", name: "Poster", voice: "brutal", display: "anton", body: "inter" },
  { id: "block", name: "Block", voice: "brutal", display: "archivoblack", body: "archivo" },
  { id: "headline", name: "Headline", voice: "brutal", display: "bebas", body: "roboto" },
  { id: "bulletin", name: "Bulletin", voice: "brutal", display: "oswald", body: "sourcesans" },

  { id: "notebook", name: "Notebook", voice: "handwritten", display: "caveat", body: "nunito" },
  { id: "margin", name: "Margin", voice: "handwritten", display: "kalam", body: "karla" },
  { id: "sketch", name: "Sketch", voice: "handwritten", display: "patrickhand", body: "lato" },
  { id: "doodle", name: "Doodle", voice: "handwritten", display: "gochihand", body: "rubik" },
];

export const pairById = (id: string): Pair | undefined => PAIRS.find((p) => p.id === id);

/** The pair a theme is currently set in, if its two faces are one. */
export const pairOf = (theme: Pick<Theme, "displayFont" | "bodyFont">): Pair | undefined =>
  PAIRS.find((p) => p.display === theme.displayFont && p.body === (theme.bodyFont ?? theme.displayFont));

/** The theme with the pair's two faces. */
export const withPair = <T extends Theme>(theme: T, pair: Pair): T => ({ ...theme, displayFont: pair.display, bodyFont: pair.body });
